      "numero": 12,
      "ar": "وَالَّذِي خَلَقَ الْأَزْوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ الْفُلْكِ وَالْأَنْعَٰمِ مَا تَرْكَبُونَ",
